mapper.select:
SELECT A.BOOK_DATE AS bookDate, A.VOUCH_NUM AS vouchNum, A.BOOKSET_ID AS booksetId, C.BOOKSET_NAME AS booksetName, B.BUSI_ID AS busiId, IFNULL(D.FINPROD_ABBR, F.ACCT_NAME) AS finprodAbbr, B.SUBJECT_NO AS subjectNo, E.SUBJECT_NAME AS subjectName, B.CD_FLAG AS cdFlag, E.BAL_FLAG AS balFlag, B.CCY AS ccy, B.HAPPEN_AMT AS happenAmt, B.HAPPEN_AMT AS balance,
IFNULL(B.HAPPEN_NUMBER,0) AS happenNumber, A.TRADE_ID AS tradeId, A.COM_TABLE_ID AS comTableId FROM bok_VOUCH_MAIN A LEFT JOIN bok_VOUCH_DETAIL B ON A.VOUCH_NUM = B.VOUCH_NUM INNER JOIN BOK_BOOKSET C ON A.BOOKSET_ID = C.BOOKSET_ID LEFT JOIN FIN_PRODUCT D ON D.FINPROD_ID = B.BUSI_ID INNER JOIN BOK_SUBJECT E ON E.BOOKSET_ID = C.BOOKSET_ID_TMPL AND B.SUBJECT_NO = E.SUBJECT_NO left join STL_CAPACCT_INFO F on F.acct_no = B.BUSI_ID WHERE 1=1
AND (A.COM_TABLE_ID IN
null) or A.COM_TABLE_ID in (
#{item}
)
AND (C.BOOKSET_Id IN
null) or C.BOOKSET_Id in (
#{item}
)
AND B.SUBJECT_NO IN
#{item}
AND upper(B.BUSI_ID) like concat_ws('','%',#{busiId},'%')
AND B.CCY=#{ccy}
AND A.BOOK_DATE >= #{bookDateBegin}
AND A.BOOK_DATE <= #{bookDateEnd}
ORDER BY A.BOOK_DATE DESC,A.VOUCH_NUM DESC

SELECT A.BOOK_DATE AS bookDate, A.VOUCH_NUM AS vouchNum, A.BOOKSET_ID AS booksetId, C.BOOKSET_NAME AS booksetName, B.BUSI_ID AS busiId, D.FINPROD_ABBR AS finprodAbbr, B.SUBJECT_NO AS subjectNo, E.SUBJECT_NAME AS subjectName, B.CD_FLAG AS cdFlag, E.BAL_FLAG AS balFlag, B.CCY AS ccy, B.B_CCY AS bCcy, B.HAPPEN_AMT AS happenAmt, B.B_HAPPEN_AMT AS bHappenAmt, B.HAPPEN_AMT AS balance,
IFNULL(B.HAPPEN_NUMBER,0) AS happenNumber, A.TRADE_ID AS tradeId, A.COM_TABLE_ID AS comTableId, A.BUS_VOUCHNUM AS busVouchnum FROM bok_VOUCH_MAIN A LEFT JOIN bok_VOUCH_DETAIL B ON A.VOUCH_NUM = B.VOUCH_NUM INNER JOIN BOK_BOOKSET C ON A.BOOKSET_ID = C.BOOKSET_ID LEFT JOIN FIN_PRODUCT D ON D.FINPROD_ID = B.BUSI_ID INNER JOIN BOK_SUBJECT E ON E.BOOKSET_ID = C.BOOKSET_ID_TMPL AND B.SUBJECT_NO = E.SUBJECT_NO WHERE C.BOOKSET_TYPE = #{booksetType}
AND A.COM_TABLE_ID IN
#{comTableId}
AND C.BOOKSET_Id IN
#{booksetId}
AND B.SUBJECT_NO IN
#{subjectNo}
AND upper(B.BUSI_ID) like concat_ws('','%',#{busiId},'%')
AND B.CCY=#{ccy}
AND A.BOOK_DATE >= #{bookDateBegin}
AND A.BOOK_DATE <= #{bookDateEnd}
ORDER BY A.BOOK_DATE DESC,A.VOUCH_NUM DESC
